// Conceptual 3D-style SVG illustrations generated by code.
// They are NOT product photos: each one is chosen by keywords in the product name and tinted per product.
let _gid = 0;
const KINDS = [["bottle",/BOTTLE/],["heart",/HEART/],["bag",/BAG|BASKET|TOWEL/],["cup",/MUG|CUP|TEA|COFFEE|JAR|TIN|CAKE|HOLDER/],["candle",/CANDLE/],["lamp",/LIGHT|LAMP|BELL|CLOCK/],["panel",/FRAME|CARD|SIGN|BUNTING|PAPER|TISSUE|NOTE|SLATE/],["pet",/MICE|DOLL|TOY|BIRD|BEAR/]];
const kindOf = n => (KINDS.find(k => k[1].test(n.toUpperCase())) || ["box"])[0];

function art(name) {
  const h = hueFor(name), id = "a" + (++_gid), c = (l, s = 75) => `hsl(${h} ${s}% ${l}%)`;
  const S = `url(#${id}s)`, R = `url(#${id}r)`;
  const defs = `<linearGradient id="${id}s" x1="0" x2="1"><stop offset="0" stop-color="${c(66)}"/><stop offset=".55" stop-color="${c(46)}"/><stop offset="1" stop-color="${c(26)}"/></linearGradient>
    <radialGradient id="${id}r" cx=".35" cy=".3" r=".8"><stop offset="0" stop-color="${c(78)}"/><stop offset=".6" stop-color="${c(48)}"/><stop offset="1" stop-color="${c(24)}"/></radialGradient>
    <radialGradient id="${id}h"><stop offset="0" stop-color="#000" stop-opacity=".5"/><stop offset="1" stop-color="#000" stop-opacity="0"/></radialGradient>`;
  const W = `fill="#fff" fill-opacity=".25"`;
  const shapes = {
    box: `<polygon points="100,48 160,78 100,108 40,78" fill="${c(74)}"/><polygon points="40,78 100,108 100,168 40,138" fill="${c(50)}"/><polygon points="100,108 160,78 160,138 100,168" fill="${c(30)}"/><path d="M100 48V108M40 78H160" stroke="#fff" stroke-opacity=".55" stroke-width="9"/><circle cx="100" cy="78" r="9" fill="#fff" fill-opacity=".85"/>`,
    cup: `<path d="M145 88q34 4 0 46" fill="none" stroke="${c(50)}" stroke-width="10"/><path d="M55 70V148A45 14 0 0 0 145 148V70Z" fill="${S}"/><ellipse cx="100" cy="70" rx="45" ry="14" fill="${c(80)}"/><ellipse cx="100" cy="70" rx="36" ry="10" fill="${c(22)}"/>`,
    candle: `<path d="M72 62V148A28 9 0 0 0 128 148V62Z" fill="${S}"/><ellipse cx="100" cy="62" rx="28" ry="9" fill="${c(80)}"/><rect x="98" y="48" width="4" height="14" fill="${c(20)}"/><path d="M100 14q-13 20 0 34q13 -14 0 -34z" fill="#fde68a"/>`,
    lamp: `<circle cx="100" cy="86" r="46" fill="${R}"/><circle cx="100" cy="86" r="20" ${W}/><rect x="80" y="126" width="40" height="28" rx="5" fill="${S}"/><ellipse cx="100" cy="154" rx="20" ry="6" fill="${c(24)}"/>`,
    bag: `<path d="M76 82C76 38 124 38 124 82" fill="none" stroke="${c(80)}" stroke-width="7"/><path d="M48 80H152L162 160H38Z" fill="${S}"/><path d="M48 80H152L154 98H46Z" fill="${c(72)}" fill-opacity=".55"/>`,
    heart: `<path d="M100 162C16 106 38 40 100 80C162 40 184 106 100 162Z" fill="${R}"/><ellipse cx="72" cy="68" rx="14" ry="8" ${W} transform="rotate(-30 72 68)"/>`,
    bottle: `<rect x="64" y="62" width="72" height="100" rx="30" fill="${S}"/><rect x="87" y="34" width="26" height="34" rx="4" fill="${c(60)}"/><rect x="84" y="24" width="32" height="12" rx="4" fill="${c(80)}"/><rect x="78" y="96" width="44" height="34" rx="6" ${W}/>`,
    panel: `<path d="M150 70L166 62V142L150 150Z" fill="${c(28)}"/><path d="M50 55L150 70V150L50 135Z" fill="${S}"/><path d="M62 68L138 80V138L62 126Z" ${W}/>`,
    pet: `<circle cx="68" cy="56" r="17" fill="${c(44)}"/><circle cx="132" cy="56" r="17" fill="${c(44)}"/><circle cx="100" cy="98" r="58" fill="${R}"/><circle cx="80" cy="92" r="6" fill="#0a1a38"/><circle cx="120" cy="92" r="6" fill="#0a1a38"/><ellipse cx="100" cy="112" rx="10" ry="7" fill="${c(82)}"/>`
  };
  return `<svg viewBox="0 0 200 190" role="img" aria-label="Conceptual illustration: ${esc(name.toLowerCase())}"><defs>${defs}</defs><ellipse cx="100" cy="172" rx="62" ry="10" fill="url(#${id}h)"/>${shapes[kindOf(name)]}</svg>`;
}

// Real render if images/<slug>.jpg is listed in images.js, otherwise the generated SVG illustration
const slugOf = n => n.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
function visual(name) {
  return (typeof PHOTOS !== "undefined" && PHOTOS.has(slugOf(name)))
    ? `<img src="images/${slugOf(name)}.jpg" alt="${esc(name.toLowerCase())}" loading="lazy" width="262" height="262">`
    : art(name);
}
